<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"></script>
<script>
(()=>{const p=['#07988a','#315b7c','#f2b84b','#db5560','#52a7c1','#8a6fc2'];const o={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true,padding:18}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#edf1f4'}}}};const b=document.getElementById('dashBarChart');if(b)new Chart(b,{type:'bar',data:{labels:@json($barChart['labels']??[]),datasets:(@json($barChart['datasets']??[])).map((d,i)=>({...d,backgroundColor:d.color||p[i],borderRadius:6,borderSkipped:false}))},options:o});const d=document.getElementById('dashDoughnutChart');if(d)new Chart(d,{type:'doughnut',data:{labels:@json($doughnutChart['labels']??[]),datasets:[{data:@json($doughnutChart['data']??[]),backgroundColor:p,borderColor:'#fff',borderWidth:3}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:o.plugins}});const l=document.getElementById('dashLineChart');if(l)new Chart(l,{type:'line',data:{labels:@json($lineChart['labels']??[]),datasets:(@json($lineChart['datasets']??[])).map((d,i)=>({...d,borderColor:d.color||p[i],backgroundColor:(d.color||p[i])+'18',fill:true,tension:.35,pointRadius:4}))},options:o})})();
@if($performanceAnalytics && $performanceAnalytics['hasData'])
(()=>{const a=@json($performanceAnalytics);const common={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true}}},scales:{y:{beginAtZero:true,max:100,grid:{color:'#edf1f4'}},x:{grid:{display:false}}}};new Chart(document.getElementById('performanceTrendChart'),{type:'line',data:{labels:a.trend.labels,datasets:[{label:'Achievement %',data:a.trend.data,borderColor:'#07988a',backgroundColor:'#07988a20',fill:true,tension:.35,spanGaps:true}]},options:common});new Chart(document.getElementById('performanceBandChart'),{type:'pie',data:{labels:a.bands.labels,datasets:[{data:a.bands.data,backgroundColor:['#00B050','#92D050','#FFC000','#FF0000','#C00000'],borderColor:'#fff',borderWidth:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:common.plugins}});const dep=document.getElementById('departmentPerformanceChart');if(dep)new Chart(dep,{type:'bar',data:{labels:a.departments.labels,datasets:[{label:'Achievement %',data:a.departments.data,backgroundColor:'#315b7c',borderRadius:6}]},options:{...common,indexAxis:'y',scales:{x:{beginAtZero:true,max:100},y:{grid:{display:false}}}}});new Chart(document.getElementById('kpiRankingChart'),{type:'bar',data:{labels:a.ranking.labels,datasets:[{label:'Achievement %',data:a.ranking.data,backgroundColor:'#52a7c1',borderRadius:6}]},options:{...common,indexAxis:'y',scales:{x:{beginAtZero:true,max:100},y:{grid:{display:false}}}}});})();
@if($performanceAnalytics['comparison']['hasPrevious'])
(()=>{const c=@json($performanceAnalytics['comparison']);const options={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true}}},scales:{y:{beginAtZero:true,max:100,grid:{color:'#edf1f4'}},x:{grid:{display:false}}}};new Chart(document.getElementById('yearComparisonTrendChart'),{type:'line',data:{labels:c.trend.labels,datasets:[{label:String(c.currentYear),data:c.trend.current,borderColor:'#07988a',backgroundColor:'#07988a18',tension:.3,spanGaps:true},{label:String(c.previousYear),data:c.trend.previous,borderColor:'#8b98a5',backgroundColor:'#8b98a518',tension:.3,spanGaps:true}]},options});new Chart(document.getElementById('kpiComparisonChart'),{type:'bar',data:{labels:c.kpis.labels,datasets:[{label:String(c.currentYear),data:c.kpis.current,backgroundColor:'#07988a',borderRadius:5},{label:String(c.previousYear),data:c.kpis.previous,backgroundColor:'#a9b4bd',borderRadius:5}]},options:{...options,indexAxis:'y',scales:{x:{beginAtZero:true,max:100},y:{grid:{display:false}}}}});const d=document.getElementById('departmentYearComparisonChart');if(d)new Chart(d,{type:'bar',data:{labels:c.departments.labels,datasets:[{label:String(c.currentYear),data:c.departments.current,backgroundColor:'#315b7c',borderRadius:5},{label:String(c.previousYear),data:c.departments.previous,backgroundColor:'#c5cdd4',borderRadius:5}]},options:{...options,indexAxis:'y',scales:{x:{beginAtZero:true,max:100},y:{grid:{display:false}}}}});})();
